+
+        assertResultConvI2L(0);
+        assertResultConvI2L(10);
+        assertResultConvI2L(-10);
+        assertResultConvI2L(Integer.MIN_VALUE);
+        assertResultConvI2L(Integer.MAX_VALUE);
+        assertResultConvI2L(a);
+    }
